values ('bbbb0002-0000-4000-8000-000000000032', 'en', null, 'Statistics with Python', 'Compute real statistics in your browser with numpy and pandas — measures of center and spread, correlation, standardization, and grouped summaries — every result auto-checked. Structure informed by the open textbook OpenIntro Statistics by Diez, Cetinkaya-Rundel, and Barr (CC BY-SA 3.0).', null, 'foundations', 32, true, 'science', '{bbbb0002-0000-4000-8000-000000000028}')
