insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000032', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The mean of a dataset is…","options":["the middle value","the sum divided by the count","the most frequent value","the largest value"],"answer":1,"explanation":"The mean (average) is the sum of the values divided by how many there are."},{"prompt":"The median is…","options":["the average","the middle value when sorted","the range","the sum"],"answer":1,"explanation":"The median is the middle value (or the average of the two middle values) once the data is sorted."},{"prompt":"The standard deviation measures…","options":["the center","how spread out the values are","the count","the largest gap only"],"answer":1,"explanation":"Standard deviation summarizes how far values typically fall from the mean — the spread."},{"prompt":"A correlation coefficient of -1 means…","options":["no relationship","a perfect negative linear relationship","a perfect positive relationship","an error"],"answer":1,"explanation":"Correlation runs from -1 (perfect negative) through 0 (none) to +1 (perfect positive)."},{"prompt":"A z-score tells you…","options":["the raw value","how many standard deviations a value is from the mean","the median","the count"],"answer":1,"explanation":"A z-score standardizes a value: (value - mean) / standard deviation."},{"prompt":"If the mean is much larger than the median, the data is likely…","options":["symmetric","right-skewed (a few large values)","left-skewed","constant"],"answer":1,"explanation":"A long right tail pulls the mean above the median — right skew."}]}'::jsonb, null, 8),
  (2, 'Measures of center and spread', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute the mean, median, and standard deviation of a dataset with numpy, and say what each tells you. Warm-up: for [1, 2, 3, 4, 5], what is the mean and what is the median?"},{"heading":"The idea","text":"A dataset has a center and a spread. The mean is the sum divided by the count: np.mean(a). The median is the middle value once sorted: np.median(a) — robust to a few extreme values. Spread is summarized by the standard deviation, the typical distance from the mean: np.std(a) (population version, dividing by n). A larger std means the values are more spread out. When the mean sits well above the median, a few large values are stretching the right tail (right skew)."},{"heading":"Worked examples","text":"For a = [1, 2, 3, 4, 5]: mean = 15/5 = 3.0; median = 3.0 (the middle value); variance = mean of squared distances = (4+1+0+1+4)/5 = 2, so std = sqrt(2) = 1.41. For a = [2, 4, 6, 8]: mean = 5.0; median = 5.0 (average of 4 and 6); std = sqrt(((9+1+1+9)/4)) = sqrt(5) = 2.24. A single value [10] has mean 10, median 10, std 0 — no spread."},{"heading":"Your turn","text":"Compute by hand, then check with numpy. 1) mean of [10, 20, 30]. 2) median of [3, 1, 2]. 3) median of [1, 2, 3, 4]. 4) std of [5, 5, 5]. 5) which is more robust to an outlier, mean or median? Answers: 1) 20.0. 2) 2. 3) 2.5. 4) 0.0. 5) the median."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting to sort before taking a median by hand (numpy sorts for you). Mistake: assuming np.std is the sample std — by default it is the population std (ddof=0). Exit: (a) Which measure of center resists outliers? (b) What does a std of 0 mean? Answers: the median; every value is identical."}]}'::jsonb, 'numpy''s std() uses the POPULATION standard deviation by default (dividing by n). This course uses that convention throughout — np.std(a) with no ddof.', 12),
  (3, 'Code: center and spread', 'code', '{"language":"python","packages":["numpy"],"prompt":"Write summary_stats(nums) that returns a dict with ''mean'', ''median'', and ''std'' (population standard deviation) of the list nums, each rounded to 2 decimals, using numpy.","instructions":"numpy is importable as `import numpy as np`. Use np.mean, np.median, and np.std (its default is the population std). Round each to 2 decimals. First run loads the runtime + numpy once.","starter":"import numpy as np\n\ndef summary_stats(nums):\n    # return {''mean'': .., ''median'': .., ''std'': ..} rounded to 2 decimals\n    return {}\n","tests":[{"label":"summary_stats([1,2,3,4,5])","expr":"summary_stats([1,2,3,4,5]) == {''mean'': 3.0, ''median'': 3.0, ''std'': 1.41}"},{"label":"summary_stats([2,4,6,8])","expr":"summary_stats([2,4,6,8]) == {''mean'': 5.0, ''median'': 5.0, ''std'': 2.24}"},{"label":"single value has zero spread","expr":"summary_stats([10]) == {''mean'': 10.0, ''median'': 10.0, ''std'': 0.0}"}],"solution":"import numpy as np\n\ndef summary_stats(nums):\n    a = np.array(nums, dtype=float)\n    return {\n        ''mean'': round(float(a.mean()), 2),\n        ''median'': round(float(np.median(a)), 2),\n        ''std'': round(float(a.std()), 2),\n    }\n"}'::jsonb, null, 13),
  (4, 'Correlation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute the Pearson correlation between two variables with numpy and interpret its sign and strength. Warm-up: if y always equals 2x, what correlation do you expect?"},{"heading":"The idea","text":"The Pearson correlation coefficient, r, measures how strongly two numeric variables move together in a straight line. It ranges from -1 to +1: +1 is a perfect upward line, -1 a perfect downward line, 0 no linear relationship. In numpy, np.corrcoef(xs, ys) returns a 2x2 matrix; the correlation between the two is the off-diagonal entry [0][1]. Correlation is not causation, and r near 0 only means no LINEAR trend — a curved relationship can still exist."},{"heading":"Worked examples","text":"If ys = 2 * xs (e.g. xs = [1,2,3], ys = [2,4,6]), r = 1.0 exactly — a perfect positive line. If ys decreases as xs increases (xs = [1,2,3], ys = [6,4,2]), r = -1.0. Reading it off numpy: np.corrcoef([1,2,3], [2,4,6])[0][1] is 1.0. Scaling does not change r: [0,1,2,3,4] vs [0,2,4,6,8] is still 1.0. A constant variable has zero spread, so its correlation is undefined (numpy returns nan) — avoid correlating against a constant."},{"heading":"Your turn","text":"Predict r. 1) xs=[1,2,3], ys=[10,20,30]. 2) xs=[1,2,3], ys=[3,2,1]. 3) xs=[1,2,3,4], ys=[4,3,2,1]. 4) Does r change if you swap xs and ys? Answers: 1) 1.0. 2) -1.0. 3) -1.0. 4) No — correlation is symmetric."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading np.corrcoef''s diagonal (always 1.0) instead of the off-diagonal [0][1]. Mistake: claiming causation from a high r. Exit: (a) What is the range of r? (b) Which matrix entry is the correlation of x and y? Answers: -1 to +1; the off-diagonal [0][1]."}]}'::jsonb, 'Correlation measures LINEAR association and is symmetric: corr(x, y) = corr(y, x). It says nothing about causation, and a value near 0 only rules out a LINEAR relationship.', 11),
  (5, 'Code: correlation coefficient', 'code', '{"language":"python","packages":["numpy"],"prompt":"Write correlation(xs, ys) that returns the Pearson correlation coefficient of two equal-length lists, rounded to 2 decimals, using numpy.","instructions":"Use np.corrcoef(xs, ys) and read the off-diagonal entry [0][1]. Round to 2 decimals and return a float.","starter":"import numpy as np\n\ndef correlation(xs, ys):\n    # return the Pearson r of xs and ys, rounded to 2 decimals\n    return 0.0\n","tests":[{"label":"perfect positive is 1.0","expr":"correlation([1,2,3],[2,4,6]) == 1.0"},{"label":"perfect negative is -1.0","expr":"correlation([1,2,3],[6,4,2]) == -1.0"},{"label":"scaling does not change r","expr":"correlation([0,1,2,3,4],[0,2,4,6,8]) == 1.0"},{"label":"returns a float","expr":"isinstance(correlation([1,2],[1,2]), float)"}],"solution":"import numpy as np\n\ndef correlation(xs, ys):\n    return round(float(np.corrcoef(xs, ys)[0][1]), 2)\n"}'::jsonb, null, 13),
  (6, 'Grouped summaries with pandas', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Summarize a column and compute a statistic per group with pandas. Warm-up: how would you get the average score for each class in a table of students?"},{"heading":"The idea","text":"A pandas column (Series) computes statistics directly: df[''score''].mean(), .median(), .min(), .max(), .count(). To summarize per category, group first: df.groupby(''group'')[''value''].mean() returns one mean per group, which .to_dict() turns into a plain dict. df.describe() prints count, mean, std, min, quartiles, and max for every numeric column at once — a fast first look at a dataset."},{"heading":"Worked examples","text":"For df with columns group and value: df[''value''].mean() is the overall mean. df.groupby(''group'')[''value''].mean() gives a Series indexed by group; add .round(2).to_dict() to get e.g. {''A'': 2.5, ''B'': 4.0}. Counting per group: df.groupby(''group'')[''value''].count(). Multiple stats at once: df.groupby(''group'')[''value''].agg([''mean'', ''max''])."},{"heading":"Your turn","text":"For df(group, value): 1) The overall mean of value. 2) The mean value per group as a dict. 3) The number of rows per group. 4) The single largest value. Answers: 1) df[''value''].mean(); 2) df.groupby(''group'')[''value''].mean().to_dict(); 3) df.groupby(''group'')[''value''].count().to_dict(); 4) df[''value''].max()."},{"heading":"Common mistakes & exit ticket","text":"Mistake: expecting pandas .std() to match numpy''s — pandas defaults to the sample std (ddof=1), numpy to the population std. Mistake: forgetting .to_dict() and comparing a Series to a dict. Exit: (a) How do you get a mean per group? (b) What does df.describe() give you? Answers: df.groupby(key)[col].mean(); a table of summary statistics per numeric column."}]}'::jsonb, 'pandas Series have the same statistics built in: s.mean(), s.median(), s.std() (note: pandas std defaults to the SAMPLE std, ddof=1, unlike numpy). df.describe() gives a whole table of summaries at once.', 11),
  (7, 'Code: mean per group', 'code', '{"language":"python","packages":["pandas"],"prompt":"Write mean_by_group(data) that, given a DataFrame with columns ''group'' and ''value'', returns a dict mapping each group to its mean value, rounded to 2 decimals.","instructions":"A sample DataFrame `df` is provided. Group by ''group'', take the mean of ''value'', round to 2, and return a plain dict (.to_dict()).","starter":"import pandas as pd\n\ndf = pd.DataFrame({\n    ''group'': [''A'', ''B'', ''A'', ''B'', ''A''],\n    ''value'': [10, 20, 20, 40, 30],\n})\n\ndef mean_by_group(data):\n    # return {group: mean value rounded to 2}\n    return {}\n","tests":[{"label":"means per group","expr":"mean_by_group(df) == {''A'': 20.0, ''B'': 30.0}"},{"label":"A''s mean is 20.0","expr":"mean_by_group(df)[''A''] == 20.0"},{"label":"returns a dict","expr":"isinstance(mean_by_group(df), dict)"}],"solution":"import pandas as pd\n\ndf = pd.DataFrame({\n    ''group'': [''A'', ''B'', ''A'', ''B'', ''A''],\n    ''value'': [10, 20, 20, 40, 30],\n})\n\ndef mean_by_group(data):\n    return data.groupby(''group'')[''value''].mean().round(2).to_dict()\n"}'::jsonb, null, 13),
  (8, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The mean of [2, 4, 6, 8] is…","options":["4","5","6","20"],"answer":1,"explanation":"(2+4+6+8)/4 = 20/4 = 5."},{"prompt":"The median of [1, 2, 3, 4] is…","options":["2","2.5","3","2.25"],"answer":1,"explanation":"The average of the two middle values, (2+3)/2 = 2.5."},{"prompt":"np.corrcoef(xs, ys) gives the correlation of x and y at…","options":["entry [0][0]","entry [0][1]","entry [1][1]","the sum of the matrix"],"answer":1,"explanation":"The diagonal is always 1.0; the off-diagonal [0][1] (= [1][0]) is r."},{"prompt":"A z-score of +2 means the value is…","options":["twice the mean","two standard deviations above the mean","the second largest","2% above average"],"answer":1,"explanation":"z = (value - mean) / std, so +2 is two std above the mean."},{"prompt":"To get the mean of ''value'' per ''group'' as a dict, you use…","options":["df[''value''].mean()","df.groupby(''group'')[''value''].mean().to_dict()","df.describe()","df.sort_values(''group'')"],"answer":1,"explanation":"Group, take the mean of the column, then .to_dict()."},{"prompt":"A std of 0 tells you…","options":["the values are all identical","the mean is 0","there is one value","an error occurred"],"answer":0,"explanation":"Zero spread means every value equals the mean — they are all the same."}]}'::jsonb, null, 8),
  (9, 'Code: standardize with z-scores', 'code', '{"language":"python","packages":["numpy"],"prompt":"Write zscores(nums) that returns a list of z-scores for the numbers: each value''s (value - mean) / std, using the population std, rounded to 2 decimals.","instructions":"Compute the mean and std once with numpy, then map each value to its z-score. Return a plain list of floats.","starter":"import numpy as np\n\ndef zscores(nums):\n    # return [(x - mean) / std rounded to 2 for each x]\n    return []\n","tests":[{"label":"zscores([1,2,3])","expr":"zscores([1,2,3]) == [-1.22, 0.0, 1.22]"},{"label":"zscores([10,20,30,40])","expr":"zscores([10,20,30,40]) == [-1.34, -0.45, 0.45, 1.34]"},{"label":"same length as input","expr":"len(zscores([5,6,7,8,9])) == 5"}],"solution":"import numpy as np\n\ndef zscores(nums):\n    a = np.array(nums, dtype=float)\n    m = a.mean()\n    s = a.std()\n    return [round(float((x - m) / s), 2) for x in a]\n"}'::jsonb, null, 14),
  (10, 'Capstone: describe a dataset', 'code', '{"language":"python","packages":["pandas"],"prompt":"Write describe_scores(data) that, given a DataFrame with a ''score'' column, returns a dict with ''count'' (int), ''mean'' (rounded to 2), ''min'' (int), and ''max'' (int).","instructions":"Use the Series methods on data[''score'']: .count(), .mean(), .min(), .max(). A sample DataFrame `df` is provided.","starter":"import pandas as pd\n\ndf = pd.DataFrame({''score'': [55, 90, 70, 85, 60, 100]})\n\ndef describe_scores(data):\n    # return {''count'': int, ''mean'': rounded 2, ''min'': int, ''max'': int}\n    return {}\n","tests":[{"label":"describes the sample data","expr":"describe_scores(df) == {''count'': 6, ''mean'': 76.67, ''min'': 55, ''max'': 100}"},{"label":"works on another frame","expr":"describe_scores(pd.DataFrame({''score'': [10, 20, 30]})) == {''count'': 3, ''mean'': 20.0, ''min'': 10, ''max'': 30}"},{"label":"count is an int","expr":"isinstance(describe_scores(df)[''count''], int)"}],"solution":"import pandas as pd\n\ndf = pd.DataFrame({''score'': [55, 90, 70, 85, 60, 100]})\n\ndef describe_scores(data):\n    s = data[''score'']\n    return {\n        ''count'': int(s.count()),\n        ''mean'': round(float(s.mean()), 2),\n        ''min'': int(s.min()),\n        ''max'': int(s.max()),\n    }\n"}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000032' and l.position = v.pos
);
